import type { NextConfig } from "next";

// Kora is a pure client-side prototype (all data is mock data held in React context),
// so we keep the default rendering model and skip Cache Components / partial prefetching.
const nextConfig: NextConfig = {
  turbopack: {
    rules: {
      // Tailwind v4 is compiled through the Turbopack loader generated by create-next-app.
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
